 *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

  :root {
    --navy: #0D1B2A;
    --navy-mid: #1a2f44;
    --gold: #C9A84C;
    --gold-light: #e2c47a;
    --off-white: #F5F5F3;
    --stone: #E8E0D0;
    --text-dark: #1a1a1a;
    --text-body: #3A3A3A;
    --text-muted: #7a7a7a;
    --border: #ddd;
  }

  html { scroll-behavior: smooth; }

  body {
    font-family: 'Inter', sans-serif;
    color: var(--text-body);
    background: var(--off-white);
    font-size: 16px;
    line-height: 1.7;
  }

  /* ── NAV ── */
  nav {
    position: fixed; top: 0; left: 0; right: 0; z-index: 100;
    background: rgba(13,27,42,0.97);
    backdrop-filter: blur(8px);
    display: flex; align-items: center; justify-content: space-between;
    padding: 0 6vw; height: 68px;
    border-bottom: 1px solid rgba(201,168,76,0.2);
  }

  .nav-logo {
    font-family: 'Cormorant Garant', serif;
    font-size: 1.5rem; font-weight: 600;
    color: #fff; letter-spacing: 0.02em;
    cursor: pointer; text-decoration: none;
  }
  .nav-logo span { color: var(--gold); }

  .nav-links { display: flex; gap: 2.5rem; list-style: none; }
  .nav-links a {
    font-size: 0.78rem; font-weight: 500; letter-spacing: 0.1em;
    text-transform: uppercase; color: rgba(255,255,255,0.7);
    text-decoration: none; transition: color 0.2s;
    cursor: pointer;
  }
  .nav-links a:hover, .nav-links a.active { color: var(--gold); }

  .nav-cta {
    font-size: 0.78rem; font-weight: 500; letter-spacing: 0.08em;
    text-transform: uppercase; color: var(--gold);
    border: 1px solid rgba(201,168,76,0.5);
    padding: 8px 20px; cursor: pointer;
    text-decoration: none;
    transition: background 0.2s, color 0.2s;
  }
  .nav-cta:hover { background: var(--gold); color: var(--navy); }

  .hamburger { display: none; flex-direction: column; gap: 5px; cursor: pointer; }
  .hamburger span { display: block; width: 24px; height: 2px; background: #fff; transition: 0.3s; }

  /* ── PAGES ── */
  .page { display: none; padding-top: 68px; min-height: 100vh; }
  .page.active { display: block; }

  /* ── HOME ── */
  .hero {
    background: linear-gradient(rgba(0,0,0,0.6), rgba(0,0,0,0.6)),
            url('data:image/jpeg;base64,') center/cover no-repeat;
    min-height: calc(100vh - 68px);
    display: flex; align-items: center;
    padding: 8vh 6vw;
    position: relative; overflow: hidden;
  }
  .hero::before {
    content: '';
    position: absolute; top: 0; right: 0;
    width: 45%; height: 100%;
    background: linear-gradient(135deg, transparent 0%, rgba(201,168,76,0.04) 100%);
    pointer-events: none;
  }
  .hero-grid-bg {
    position: absolute; top: 0; left: 0; right: 0; bottom: 0;
    background-image:
      linear-gradient(rgba(201,168,76,0.04) 1px, transparent 1px),
      linear-gradient(90deg, rgba(201,168,76,0.04) 1px, transparent 1px);
    background-size: 60px 60px;
    pointer-events: none;
  }

  .hero-content { position: relative; z-index: 1; max-width: 760px; }

  .hero-eyebrow {
    font-size: 0.72rem; font-weight: 500; letter-spacing: 0.18em;
    text-transform: uppercase; color: var(--gold);
    margin-bottom: 1.5rem;
    display: flex; align-items: center; gap: 12px;
  }
  .hero-eyebrow::before {
    content: ''; display: block; width: 32px; height: 1px; background: var(--gold);
  }

  .hero h1 {
    font-family: 'Cormorant Garant', serif;
    font-size: clamp(2.8rem, 6vw, 5.2rem);
    font-weight: 500; line-height: 1.08;
    color: #fff; margin-bottom: 0.4rem;
  }
  .hero h1 em { font-style: italic; color: var(--gold-light); }

  .hero-rule { width: 80px; height: 1px; background: var(--gold); margin: 2rem 0; }

  .hero-sub {
    font-size: 1.05rem; font-weight: 300; color: rgba(255,255,255,0.65);
    max-width: 520px; line-height: 1.8; margin-bottom: 3rem;
  }

  .hero-actions { display: flex; gap: 1rem; flex-wrap: wrap; }

  .btn-primary {
    background: var(--gold); color: var(--navy);
    padding: 14px 36px; font-size: 0.8rem; font-weight: 600;
    letter-spacing: 0.1em; text-transform: uppercase;
    border: none; cursor: pointer; transition: background 0.2s;
    text-decoration: none; display: inline-block;
  }
  .btn-primary:hover { background: var(--gold-light); }

  .btn-outline {
    background: transparent; color: #fff;
    padding: 14px 36px; font-size: 0.8rem; font-weight: 500;
    letter-spacing: 0.1em; text-transform: uppercase;
    border: 1px solid rgba(255,255,255,0.3); cursor: pointer;
    transition: border-color 0.2s, color 0.2s;
    text-decoration: none; display: inline-block;
  }
  .btn-outline:hover { border-color: #fff; color: #fff; }

  .hero-stats {
    margin-top: 5rem; padding-top: 3rem;
    border-top: 1px solid rgba(255,255,255,0.1);
    display: grid; grid-template-columns: repeat(3, auto); gap: 3rem; width: fit-content;
  }
  .stat-num {
    font-family: 'Cormorant Garant', serif;
    font-size: 2.4rem; font-weight: 600; color: var(--gold);
    line-height: 1;
  }
  .stat-label {
    font-size: 0.72rem; font-weight: 400; letter-spacing: 0.1em;
    text-transform: uppercase; color: rgba(255,255,255,0.4);
    margin-top: 4px;
  }

  /* home sections */
  .section { padding: 7rem 6vw; }
  .section-alt { background: #fff; }

  .section-eyebrow {
    font-size: 0.72rem; font-weight: 500; letter-spacing: 0.18em;
    text-transform: uppercase; color: var(--gold); margin-bottom: 1rem;
  }
  .section-title {
    font-family: 'Cormorant Garant', serif;
    font-size: clamp(2rem, 3.5vw, 3rem); font-weight: 500; line-height: 1.15;
    color: var(--navy); margin-bottom: 1.5rem;
  }
  .section-body {
    font-size: 1rem; color: var(--text-muted); max-width: 560px; line-height: 1.85;
  }

  /* services preview */
  .services-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
    gap: 1.5px; margin-top: 4rem;
    border: 1.5px solid var(--stone);
  }
  .service-card {
    padding: 2.5rem 2rem; background: var(--off-white);
    border: none; transition: background 0.25s;
    cursor: pointer;
  }
  .service-card:hover { background: var(--navy); }
  .service-card:hover .sc-num,
  .service-card:hover .sc-title,
  .service-card:hover .sc-body { color: rgba(255,255,255,0.9); }
  .service-card:hover .sc-num { color: var(--gold); }
  .service-card:hover .sc-arrow { color: var(--gold); }

  .sc-num {
    font-size: 0.7rem; font-weight: 500; letter-spacing: 0.15em;
    color: var(--gold); margin-bottom: 1.2rem;
  }
  .sc-title {
    font-family: 'Cormorant Garant', serif;
    font-size: 1.4rem; font-weight: 500; color: var(--navy);
    margin-bottom: 0.7rem; line-height: 1.2;
  }
  .sc-body { font-size: 0.88rem; color: var(--text-muted); line-height: 1.7; }
  .sc-arrow { margin-top: 1.5rem; color: var(--gold); font-size: 1.2rem; }

  /* approach strip */
  .approach-strip {
    background: var(--navy); padding: 6rem 6vw;
  }
  .approach-steps {
    display: grid; grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
    gap: 0; margin-top: 4rem;
    border-top: 1px solid rgba(255,255,255,0.1);
  }
  .step-item {
    padding: 2.5rem 1.5rem 2.5rem 0;
    border-right: 1px solid rgba(255,255,255,0.08);
  }
  .step-item:last-child { border-right: none; }
  .step-num {
    font-family: 'Cormorant Garant', serif;
    font-size: 2.5rem; font-weight: 400; color: rgba(201,168,76,0.25);
    line-height: 1; margin-bottom: 1rem;
  }
  .step-title {
    font-size: 0.82rem; font-weight: 600; letter-spacing: 0.08em;
    text-transform: uppercase; color: #fff; margin-bottom: 0.5rem;
  }
  .step-body { font-size: 0.82rem; color: rgba(255,255,255,0.4); line-height: 1.6; }

  /* why us */
  .why-grid {
    display: grid; grid-template-columns: 1fr 1fr; gap: 3rem; margin-top: 4rem;
  }
  .why-item { display: flex; gap: 1.25rem; align-items: flex-start; }
  .why-dot {
    width: 8px; height: 8px; border-radius: 50%; background: var(--gold);
    flex-shrink: 0; margin-top: 8px;
  }
  .why-text strong { font-size: 0.9rem; color: var(--navy); display: block; margin-bottom: 0.25rem; }
  .why-text p { font-size: 0.85rem; color: var(--text-muted); line-height: 1.65; }

  /* ── ABOUT ── */
  .about-hero {
    background: var(--navy); padding: 8rem 6vw 6rem;
    position: relative; overflow: hidden;
  }
  .about-hero::after {
    content: 'SOELinks'; position: absolute;
    right: 4vw; bottom: -2rem;
    font-family: 'Cormorant Garant', serif;
    font-size: 10rem; font-weight: 600; color: rgba(255,255,255,0.03);
    line-height: 1; pointer-events: none;
    white-space: nowrap;
  }
  .about-hero h1 {
    font-family: 'Cormorant Garant', serif;
    font-size: clamp(2.4rem, 5vw, 4.5rem); font-weight: 500;
    color: #fff; line-height: 1.1; max-width: 700px;
  }
  .about-hero h1 em { color: var(--gold-light); font-style: italic; }
  .about-hero p {
    margin-top: 2rem; font-size: 1rem; color: rgba(255,255,255,0.55);
    max-width: 560px; line-height: 1.85;
  }

  .about-split {
    display: grid; grid-template-columns: 1fr 1fr; gap: 5rem;
    padding: 6rem 6vw; align-items: start;
  }
  .about-split-left .label {
    font-size: 0.7rem; font-weight: 500; letter-spacing: 0.18em;
    text-transform: uppercase; color: var(--gold); margin-bottom: 1rem;
  }
  .about-split-left h2 {
    font-family: 'Cormorant Garant', serif;
    font-size: 2.4rem; font-weight: 500; color: var(--navy);
    line-height: 1.15; margin-bottom: 1.5rem;
  }
  .about-split-left p { font-size: 0.95rem; color: var(--text-muted); line-height: 1.9; margin-bottom: 1rem; }

  .about-split-right { padding-top: 2.5rem; }
  .vm-block { margin-bottom: 2.5rem; padding-bottom: 2.5rem; border-bottom: 1px solid var(--stone); }
  .vm-block:last-child { border-bottom: none; }
  .vm-label {
    font-size: 0.7rem; letter-spacing: 0.15em; text-transform: uppercase;
    color: var(--gold); font-weight: 500; margin-bottom: 0.5rem;
  }
  .vm-title {
    font-family: 'Cormorant Garant', serif;
    font-size: 1.6rem; font-weight: 500; color: var(--navy); margin-bottom: 0.6rem;
  }
  .vm-body { font-size: 0.9rem; color: var(--text-muted); line-height: 1.8; }

  /* principles */
  .principles { background: var(--off-white); padding: 6rem 6vw; }
  .principles-grid {
    display: grid; grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
    gap: 2px; margin-top: 3.5rem; background: var(--stone);
  }
  .principle-card {
    background: #fff; padding: 2.5rem 2rem;
  }
  .principle-icon {
    width: 36px; height: 36px; border: 1px solid var(--gold);
    display: flex; align-items: center; justify-content: center;
    margin-bottom: 1.5rem;
  }
  .principle-icon svg { width: 16px; height: 16px; stroke: var(--gold); fill: none; stroke-width: 1.5; }
  .principle-name {
    font-size: 0.82rem; font-weight: 600; letter-spacing: 0.08em;
    text-transform: uppercase; color: var(--navy); margin-bottom: 0.6rem;
  }
  .principle-desc { font-size: 0.85rem; color: var(--text-muted); line-height: 1.7; }

  /* founder */
  .founder { padding: 6rem 6vw; background: #fff; }
  .founder-inner {
    display: grid; grid-template-columns: auto 1fr; gap: 4rem; align-items: center;
    max-width: 900px;
  }
  .founder-monogram {
    width: 120px; height: 120px;
    border: 1px solid var(--stone);
    display: flex; align-items: center; justify-content: center;
    flex-shrink: 0;
  }
  .founder-monogram span {
    font-family: 'Cormorant Garant', serif;
    font-size: 2.8rem; font-weight: 400; color: var(--navy);
  }
  .founder-name {
    font-family: 'Cormorant Garant', serif;
    font-size: 2rem; font-weight: 500; color: var(--navy); margin-bottom: 0.25rem;
  }
  .founder-title {
    font-size: 0.75rem; font-weight: 500; letter-spacing: 0.14em;
    text-transform: uppercase; color: var(--gold); margin-bottom: 1.2rem;
  }
  .founder-bio { font-size: 0.95rem; color: var(--text-muted); line-height: 1.85; }

  /* ── SERVICES PAGE ── */
  .page-hero {
    background: var(--navy); padding: 7rem 6vw 5rem;
  }
  .page-hero h1 {
    font-family: 'Cormorant Garant', serif;
    font-size: clamp(2.4rem, 5vw, 4rem); font-weight: 500; color: #fff;
    line-height: 1.1;
  }
  .page-hero p {
    margin-top: 1.5rem; font-size: 1rem; color: rgba(255,255,255,0.5);
    max-width: 500px; line-height: 1.8;
  }

  .services-full { padding: 5rem 6vw; }
  .service-block {
    display: grid; grid-template-columns: 1fr 2fr; gap: 4rem;
    padding: 4rem 0; border-bottom: 1px solid var(--stone);
    align-items: start;
  }
  .service-block:first-child { padding-top: 0; }
  .sb-left { position: sticky; top: 100px; }
  .sb-num {
    font-family: 'Cormorant Garant', serif;
    font-size: 4rem; font-weight: 400; color: var(--stone);
    line-height: 1; margin-bottom: 0.5rem;
  }
  .sb-title {
    font-family: 'Cormorant Garant', serif;
    font-size: 1.8rem; font-weight: 500; color: var(--navy); line-height: 1.2;
  }
  .sb-body { font-size: 0.95rem; color: var(--text-muted); line-height: 1.9; margin-bottom: 1.5rem; }
  .sb-list { list-style: none; }
  .sb-list li {
    font-size: 0.88rem; color: var(--text-body);
    padding: 0.5rem 0; border-top: 1px solid var(--stone);
    display: flex; gap: 0.75rem; align-items: flex-start;
  }
  .sb-list li::before { content: '—'; color: var(--gold); flex-shrink: 0; }

  /* approach detail */
  .approach-detail { background: var(--off-white); padding: 6rem 6vw; }
  .approach-flow {
    display: grid; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
    gap: 2px; margin-top: 4rem; background: var(--stone);
  }
  .flow-step {
    background: #fff; padding: 2.5rem 2rem; position: relative;
  }
  .flow-step-num {
    font-family: 'Cormorant Garant', serif;
    font-size: 3rem; font-weight: 400; color: var(--stone);
    line-height: 1; margin-bottom: 1rem;
  }
  .flow-step-title {
    font-size: 0.8rem; font-weight: 600; letter-spacing: 0.1em;
    text-transform: uppercase; color: var(--navy); margin-bottom: 0.5rem;
  }
  .flow-step-body { font-size: 0.85rem; color: var(--text-muted); line-height: 1.7; }
  .flow-step-gold { border-top: 2px solid var(--gold); }

  /* ── CONTACT ── */
  .contact-layout {
    display: grid; grid-template-columns: 1fr 1fr; min-height: calc(100vh - 68px);
  }
  .contact-left {
    background: var(--navy); padding: 6rem 5vw;
    display: flex; flex-direction: column; justify-content: space-between;
  }
  .contact-left h2 {
    font-family: 'Cormorant Garant', serif;
    font-size: clamp(2rem, 3.5vw, 3.2rem); font-weight: 500;
    color: #fff; line-height: 1.15; margin-bottom: 1.5rem;
  }
  .contact-left h2 em { color: var(--gold-light); font-style: italic; }
  .contact-left p { font-size: 0.95rem; color: rgba(255,255,255,0.5); line-height: 1.8; max-width: 380px; }

  .contact-info { margin-top: 4rem; }
  .ci-item {
    display: flex; gap: 1.5rem; align-items: flex-start;
    padding: 1.5rem 0; border-top: 1px solid rgba(255,255,255,0.08);
  }
  .ci-label {
    font-size: 0.7rem; font-weight: 500; letter-spacing: 0.15em;
    text-transform: uppercase; color: var(--gold); min-width: 80px; padding-top: 3px;
  }
  .ci-value { font-size: 0.9rem; color: rgba(255,255,255,0.7); line-height: 1.7; }
  .ci-value a { color: rgba(255,255,255,0.7); text-decoration: none; }
  .ci-value a:hover { color: var(--gold); }

  .contact-right { background: #fff; padding: 6rem 5vw; }
  .contact-right h3 {
    font-family: 'Cormorant Garant', serif;
    font-size: 1.8rem; font-weight: 500; color: var(--navy); margin-bottom: 0.5rem;
  }
  .contact-right p { font-size: 0.9rem; color: var(--text-muted); margin-bottom: 2.5rem; }

  .form-group { margin-bottom: 1.5rem; }
  .form-label {
    display: block; font-size: 0.72rem; font-weight: 500; letter-spacing: 0.1em;
    text-transform: uppercase; color: var(--navy); margin-bottom: 0.5rem;
  }
  .form-input, .form-select, .form-textarea {
    width: 100%; padding: 12px 16px;
    border: 1px solid var(--border); background: var(--off-white);
    font-family: 'Inter', sans-serif; font-size: 0.9rem; color: var(--text-body);
    outline: none; transition: border-color 0.2s;
    -webkit-appearance: none; border-radius: 0;
  }
  .form-input:focus, .form-select:focus, .form-textarea:focus {
    border-color: var(--navy);
  }
  .form-textarea { resize: vertical; min-height: 120px; }
  .form-row { display: grid; grid-template-columns: 1fr 1fr; gap: 1rem; }

  .form-submit {
    background: var(--navy); color: #fff;
    width: 100%; padding: 15px; border: none; cursor: pointer;
    font-family: 'Inter', sans-serif; font-size: 0.8rem; font-weight: 600;
    letter-spacing: 0.12em; text-transform: uppercase;
    transition: background 0.2s; border-radius: 0;
  }
  .form-submit:hover { background: var(--navy-mid); }

  .form-note { font-size: 0.78rem; color: var(--text-muted); margin-top: 1rem; text-align: center; }

  /* success message */
  .form-success {
    display: none; text-align: center; padding: 3rem 0;
  }
  .form-success .check {
    width: 60px; height: 60px; border: 1px solid var(--gold);
    display: flex; align-items: center; justify-content: center;
    margin: 0 auto 1.5rem;
  }
  .form-success h4 {
    font-family: 'Cormorant Garant', serif;
    font-size: 1.8rem; font-weight: 500; color: var(--navy); margin-bottom: 0.5rem;
  }
  .form-success p { font-size: 0.9rem; color: var(--text-muted); }

  /* ── FOOTER ── */
  footer {
    background: var(--navy);
    padding: 4rem 6vw 2rem;
    border-top: 1px solid rgba(201,168,76,0.15);
  }
  .footer-top {
    display: grid; grid-template-columns: 1.5fr 1fr 1fr; gap: 4rem; margin-bottom: 3rem;
  }
  .footer-logo {
    font-family: 'Cormorant Garant', serif;
    font-size: 1.6rem; font-weight: 600; color: #fff; margin-bottom: 0.75rem;
  }
  .footer-logo span { color: var(--gold); }
  .footer-tagline { font-size: 0.78rem; color: rgba(255,255,255,0.3); letter-spacing: 0.1em; text-transform: uppercase; }
  .footer-col h5 {
    font-size: 0.7rem; font-weight: 600; letter-spacing: 0.15em;
    text-transform: uppercase; color: var(--gold); margin-bottom: 1.2rem;
  }
  .footer-col ul { list-style: none; }
  .footer-col ul li { margin-bottom: 0.5rem; }
  .footer-col ul li a {
    font-size: 0.85rem; color: rgba(255,255,255,0.45);
    text-decoration: none; cursor: pointer; transition: color 0.2s;
  }
  .footer-col ul li a:hover { color: rgba(255,255,255,0.85); }
  .footer-bottom {
    border-top: 1px solid rgba(255,255,255,0.08);
    padding-top: 2rem;
    display: flex; justify-content: space-between; align-items: center;
  }
  .footer-copy { font-size: 0.75rem; color: rgba(255,255,255,0.25); }
  .footer-instagram {
    font-size: 0.75rem; color: rgba(255,255,255,0.35);
    text-decoration: none; letter-spacing: 0.05em;
    transition: color 0.2s;
  }
  .footer-instagram:hover { color: var(--gold); }

  /* ── MOBILE ── */
  @media (max-width: 768px) {
    /* Nav */
    .nav-links, .nav-cta { display: none; }
    .hamburger { display: flex; }
    nav.open .nav-links {
      display: flex; flex-direction: column;
      position: absolute; top: 68px; left: 0; right: 0;
      background: var(--navy); padding: 2rem 6vw; gap: 1.5rem;
      border-top: 1px solid rgba(201,168,76,0.2);
      z-index: 99;
    }
    nav.open .nav-links a { font-size: 1rem; }

    /* Hero */
    .hero { padding: 5vh 6vw 6vh; min-height: auto; }
    .hero h1 { font-size: 2.4rem; }
    .hero-sub { font-size: 0.95rem; }
    .hero-actions { flex-direction: column; gap: 0.75rem; }
    .btn-primary, .btn-outline { text-align: center; width: 100%; padding: 14px 24px; }
    .hero-stats {
      grid-template-columns: 1fr 1fr 1fr;
      gap: 1rem; margin-top: 3rem; padding-top: 2rem;
    }
    .stat-num { font-size: 1.7rem; }
    .stat-label { font-size: 0.62rem; }

    /* Sections */
    .section { padding: 4rem 6vw; }
    .section-title { font-size: 1.9rem; }
    .why-grid { grid-template-columns: 1fr; gap: 1.5rem; }

    /* Services grid */
    .services-grid { grid-template-columns: 1fr; }

    /* Approach steps */
    .approach-strip { padding: 4rem 6vw; }
    .approach-steps { grid-template-columns: 1fr; }
    .step-item { border-right: none; border-bottom: 1px solid rgba(255,255,255,0.08); padding: 2rem 0; }
    .step-item:last-child { border-bottom: none; }

    /* About */
    .about-hero { padding: 5rem 6vw 4rem; }
    .about-hero::after { display: none; }
    .about-split { grid-template-columns: 1fr; gap: 3rem; padding: 4rem 6vw; }
    .about-split-left { position: static; }
    .principles { padding: 4rem 6vw; }
    .principles-grid { grid-template-columns: 1fr 1fr; }

    /* Founder */
    .founder { padding: 4rem 6vw; }
    .founder-inner { grid-template-columns: 1fr; gap: 2rem; }
    .founder-monogram { width: 80px; height: 80px; }
    .founder-monogram span { font-size: 2rem; }

    /* Services page */
    .page-hero { padding: 5rem 6vw 3.5rem; }
    .services-full { padding: 3rem 6vw; }
    .service-block { grid-template-columns: 1fr; gap: 1.5rem; padding: 3rem 0; }
    .sb-left { position: static; }
    .sb-num { font-size: 2.5rem; }
    .approach-detail { padding: 4rem 6vw; }
    .approach-flow { grid-template-columns: 1fr; }

    /* Contact */
    .contact-layout { grid-template-columns: 1fr; }
    .contact-left { padding: 5rem 6vw 3rem; min-height: auto; }
    .contact-right { padding: 3rem 6vw 5rem; }
    .form-row { grid-template-columns: 1fr; }

    /* Footer */
    footer { padding: 3rem 6vw 2rem; }
    .footer-top { grid-template-columns: 1fr; gap: 2rem; }
    .footer-bottom { flex-direction: column; gap: 1rem; text-align: center; }

    /* CTA sections */
    section[style*="text-align:center"] { padding: 4rem 6vw !important; }
  }